namespace QaAutomation.Core.Models;

/// <summary>A test case generated by the Tester agent. <c>Preconditions</c> is always "" (setup lives
/// in the steps). Step shape = {action, expected}.</summary>
public sealed class GeneratedTestCase
{
    public string Title { get; set; } = "";
    public string Preconditions { get; set; } = "";
    public List<TestCaseStep> Steps { get; set; } = [];
}

/// <summary>A test case returned by the Tester's feedback-driven refine pass. <c>Ref</c> ties the item
/// back to an existing draft (the draft id as a string) so the orchestrator can update it in place, or
/// is "new"/null for a freshly generated case. Otherwise identical to <see cref="GeneratedTestCase"/>.</summary>
public sealed class RefinedTestCase
{
    public string? Ref { get; set; }
    public string Title { get; set; } = "";
    public string Preconditions { get; set; } = "";
    public List<TestCaseStep> Steps { get; set; } = [];
}

/// <summary>An already-generated draft handed to the Tester's refine pass. <c>Locked</c> marks a draft
/// already pushed to ADO (immutable — passed as read-only context, never returned for edit).
/// <c>Feedback</c> is the tester's per-test note, if any.</summary>
public sealed record ExistingDraftForRefine(
    int DraftId, string Title, string Preconditions, IReadOnlyList<TestCaseStep> Steps,
    string Status, bool Locked, string? Feedback);

/// <summary>A bug generated by the Bug Writer agent. <c>ReproSteps</c> are plain strings; severity is
/// one of Critical/High/Medium/Low.</summary>
public sealed class GeneratedBug
{
    public string Title { get; set; } = "";
    public string Severity { get; set; } = "Medium";
    public string Preconditions { get; set; } = "";
    public List<string> ReproSteps { get; set; } = [];
    public string Expected { get; set; } = "";
    public string Actual { get; set; } = "";
    public string SuggestedFix { get; set; } = "";
}

/// <summary>Pass-1 per-test-case verdict from the Code Verifier. Status ∈ pass|fail|inconclusive.</summary>
public sealed class CodeVerdict
{
    public string TestCase { get; set; } = "";
    public string Status { get; set; } = "inconclusive";
    public string Evidence { get; set; } = "";
    public string Reasoning { get; set; } = "";
}

/// <summary>Pass-2 per-step verdict from the Code Verifier. Status ∈ pass|fail|inconclusive.</summary>
public sealed class StepVerdict
{
    public string Action { get; set; } = "";
    public string Expected { get; set; } = "";
    public string Status { get; set; } = "inconclusive";
    public string Actual { get; set; } = "";
}

/// <summary>A test case fed INTO the Code Verifier (from ADO-linked cases or local drafts).</summary>
public sealed class TestCaseInput
{
    public string Title { get; set; } = "";
    public string Preconditions { get; set; } = "";
    public List<TestCaseStep> Steps { get; set; } = [];
}

// ── QA Loop agent-output POCOs ────────────────────────────────────────────────

/// <summary>One route in the module's inventory.</summary>
public sealed record RouteInfo(
    string Method, string Route,
    string? RequestDto, string? ResponseDto,
    List<string> ValidationRules, List<string> AuthRequirements);

public sealed record DtoField(string Name, string Type);
public sealed record DtoInfo(string Name, List<DtoField> Fields);
public sealed record WorkflowStep(string Endpoint, string Role);
public sealed record WorkflowInfo(string Name, List<WorkflowStep> Steps);

/// <summary>Full API inventory emitted by ModuleAnalyzerAgent pass-1.</summary>
public sealed record InventoryDoc(
    string Module,
    List<RouteInfo> Routes,
    List<DtoInfo> Dtos,
    List<WorkflowInfo> Workflows);

/// <summary>One testable surface (contract / endpoint / workflow row).</summary>
public sealed class SurfaceRow
{
    public string Id { get; set; } = "";
    public TestLevel Level { get; set; }
    public string Label { get; set; } = "";
    /// <summary>gap | covered</summary>
    public string Status { get; set; } = "gap";
    public int? LinkedTestCaseId { get; set; }
    public bool Selected { get; set; } = true;
}

/// <summary>Coverage matrix emitted alongside InventoryDoc by ModuleAnalyzerAgent.</summary>
public sealed record SurfaceMatrix(string Module, List<SurfaceRow> Rows);

/// <summary>Output of ImpactAnalyzerAgent — impacted draft ids + reasoning.</summary>
public sealed class ImpactAnalysis
{
    public List<int> ImpactedDraftIds { get; set; } = [];
    public string Reasoning { get; set; } = "";
    /// <summary>high | medium | low</summary>
    public string Confidence { get; set; } = "low";
    public string? SkippedReason { get; set; }
    public bool Fallback { get; set; }
}
